using System.Globalization;
using System.Text.Json;
using System.Windows;
using System.Windows.Media;
using VisionFramework;
using VisionPluginContracts;
using W=System.Windows.Controls;
using Brushes=System.Windows.Media.Brushes;
using Color=System.Windows.Media.Color;
namespace VisionPlugins.Calibration;

/// <summary>Dedicated XML/source-derived editor. Original desktop-shell pixels remain unverified.</summary>
public sealed class NImageWindow:Window
{
 readonly ToolEditorContext context;readonly Dictionary<string,JsonElement> values;readonly W.TabControl tabs=new();readonly W.TextBlock result=new(){Margin=new Thickness(20),TextWrapping=TextWrapping.Wrap};readonly Action? clear;readonly Action<string>? save;bool building,running,continuous,closed;
 readonly W.Button once=new(){Name="ExecuteNImage",Content="执行",Width=66,Height=25},loop=new(){Name="ContinuousNImage",Content="连续执行",Width=76,Height=25};
 public NImageWindow(ToolEditorContext context,Action? clear=null,Action<string>? save=null){this.context=context;this.clear=clear;this.save=save;values=NImageParameters.Defaults();foreach(var p in context.Node.Parameters)values[p.Key]=p.Value.Clone();Width=420;Height=650;WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.NoResize;Background=new SolidColorBrush(Color.FromRgb(242,243,245));FontFamily=new("Microsoft YaHei UI");FontSize=14;WindowStartupLocation=WindowStartupLocation.CenterOwner;
  foreach(string file in new[]{"Theme.xaml","ListViewComboBoxStyle.xaml","RecScrollBarStyle.xaml","LightControls.xaml"})Resources.MergedDictionaries.Add(new ResourceDictionary{Source=new Uri("pack://application:,,,/VisionPlugins.ImageSource;component/Resources/"+file)});
  var grid=new W.Grid();grid.RowDefinitions.Add(new(){Height=new GridLength(context.Mode==ToolEditorMode.Desktop?34:0)});grid.RowDefinitions.Add(new());grid.RowDefinitions.Add(new(){Height=new GridLength(32)});var title=new W.DockPanel{Background=new SolidColorBrush(Color.FromRgb(36,36,36))};var close=Button("×",Close,"CloseNImage");close.Width=44;close.FontSize=22;W.DockPanel.SetDock(close,W.Dock.Right);title.Children.Add(close);title.Children.Add(new W.TextBlock{Text=(context.DisplayIndex is int index?index+" ":"")+context.Node.Name,Foreground=Brushes.White,FontWeight=FontWeights.Bold,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(10,0,0,0)});title.MouseLeftButtonDown+=(_,_)=>DragMove();grid.Children.Add(title);W.Grid.SetRow(tabs,1);grid.Children.Add(tabs);
  var bottom=new W.StackPanel{Orientation=W.Orientation.Horizontal,HorizontalAlignment=System.Windows.HorizontalAlignment.Right,Margin=new Thickness(0,3,14,3)};loop.Click+=async(_,_)=>{if(continuous){continuous=false;return;}if(running)return;continuous=true;loop.Content="停止";do{await Execute();if(continuous&&!closed)await Task.Delay(1);}while(continuous&&!closed);loop.Content="连续执行";};once.Click+=async(_,_)=>await Execute();bottom.Children.Add(loop);bottom.Children.Add(once);bottom.Children.Add(Button("确定",Close,"ConfirmNImage"));W.Grid.SetRow(bottom,2);grid.Children.Add(bottom);Content=new W.Border{BorderBrush=Brushes.OrangeRed,BorderThickness=new Thickness(0,context.Mode==ToolEditorMode.Desktop?1:0,0,0),Child=grid};Closed+=(_,_)=>{continuous=false;closed=true;};Build();
 }
 static W.Button Button(string text,Action click,string name=""){var b=new W.Button{Name=name,Content=text,Height=25,MinWidth=28,Margin=new Thickness(2,0,0,0)};b.Click+=(_,_)=>click();return b;}
 void Apply()=>context.Apply(values.ToDictionary(p=>p.Key,p=>p.Value.Clone()));
 void Set<T>(string key,T value){values[key]=JsonSerializer.SerializeToElement(value);Apply();}
 int I(string key)=>values[key].GetInt32();bool B(string key)=>values[key].GetBoolean();
 static void Header(W.Panel panel,string text)=>panel.Children.Add(new W.TextBlock{Text=text,FontWeight=FontWeights.Bold,Margin=new Thickness(0,12,0,12)});
 static void Row(W.Panel panel,string text,FrameworkElement field){var g=new W.Grid{MinHeight=35};g.ColumnDefinitions.Add(new(){Width=new GridLength(128)});g.ColumnDefinitions.Add(new());g.Children.Add(new W.TextBlock{Text=text,Foreground=new SolidColorBrush(Color.FromRgb(98,103,108)),VerticalAlignment=VerticalAlignment.Center});field.VerticalAlignment=VerticalAlignment.Center;W.Grid.SetColumn(field,1);g.Children.Add(field);panel.Children.Add(g);}
 W.StackPanel Page(string name,string header){var rows=new W.StackPanel{Margin=new Thickness(24,8,24,14)};tabs.Items.Add(new W.TabItem{Name=name,Header=header,Content=new W.ScrollViewer{Content=rows,VerticalScrollBarVisibility=W.ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=W.ScrollBarVisibility.Disabled}});return rows;}
 string Label(string key)=>context.SubscriptionLabel?.Invoke(key,false)??"";
 void Number(W.Panel parent,string key,string label){var spec=NImageParameters.Definitions.Single(p=>p.Name==key);double min=spec.Minimum??-double.MaxValue;if(key=="CalibPointTotalNum")min=NImageUiRules.OtherCountMinimum(I("RotPointTotalNum"));if(key=="RotPointTotalNum")min=NImageUiRules.OtherCountMinimum(I("CalibPointTotalNum"));var edit=new VisionPlugins.ImageSource.AcquisitionNumericControl{Name=key,Minimum=min,Maximum=spec.Maximum??double.MaxValue,Integer=spec.Kind==ParameterKind.Integer,Text=spec.Kind==ParameterKind.Integer?I(key).ToString(CultureInfo.InvariantCulture):values[key].GetDouble().ToString("F3",CultureInfo.InvariantCulture)};edit.ValueChanged+=v=>{if(building||closed)return;if(spec.Kind==ParameterKind.Integer)Set(key,checked((int)v));else Set(key,(double)(float)v);if(key is "CalibPointTotalNum" or "RotPointTotalNum")Build();};Row(parent,label,edit);}
 void Toggle(W.Panel parent,string key,string label){var b=new System.Windows.Controls.Primitives.ToggleButton{Name=key,IsChecked=B(key),Style=(Style)FindResource("LightSwitch")};b.Click+=(_,_)=>{if(building)return;Set(key,b.IsChecked==true);Build();};Row(parent,label,b);}
 void Choice(W.Panel parent,string key,string caption,IReadOnlyDictionary<int,string> choices){var items=choices.ToArray();var combo=new W.ComboBox{Name=key,ItemsSource=items,DisplayMemberPath="Value",SelectedValuePath="Key",SelectedValue=I(key),Height=28};combo.SelectionChanged+=(_,_)=>{if(building||combo.SelectedValue is not int v)return;Set(key,v);Build();};Row(parent,caption,combo);}
 void Input(W.Panel parent,string key,string caption,DataKind kind=DataKind.Number){var dock=new W.DockPanel();var link=Button("↗",()=>{context.PickSubscription?.Invoke(this,key,false,kind);Build();},"Subscribe"+key);W.DockPanel.SetDock(link,W.Dock.Right);dock.Children.Add(link);if(kind==DataKind.Number){var text=new W.TextBox{Name="Input"+key,Height=28,VerticalContentAlignment=VerticalAlignment.Center,Text=context.InputNumber?.Invoke(key)?.ToString("G9",CultureInfo.InvariantCulture)??Label(key)};string old=text.Text;text.LostKeyboardFocus+=(_,_)=>{if(building||closed||text.Text==old)return;try{context.SetInputNumber?.Invoke(key,string.IsNullOrWhiteSpace(text.Text)?null:double.Parse(text.Text,CultureInfo.InvariantCulture));Build();}catch(Exception ex){System.Windows.MessageBox.Show(this,ex.Message,"输入错误");text.Text=old;}};dock.Children.Add(text);}else dock.Children.Add(Button(string.IsNullOrEmpty(Label(key))?"请选择":Label(key),()=>{context.PickSubscription?.Invoke(this,key,false,kind);Build();},"Input"+key));Row(parent,caption,dock);}
 void Pair(W.Panel parent,string x,string y,string caption){var b=Button(string.IsNullOrEmpty(Label(x))&&string.IsNullOrEmpty(Label(y))?"请选择":Label(x)+" / "+Label(y),()=>{var dialog=new Window{Title=caption,Owner=this,Width=400,Height=180,WindowStartupLocation=WindowStartupLocation.CenterOwner};var rows=new W.StackPanel{Margin=new Thickness(16)};void Add(string key,string label){var text=new W.TextBox{Name="Pair"+key,Height=27,Text=context.InputNumber?.Invoke(key)?.ToString(CultureInfo.InvariantCulture)??""};text.LostKeyboardFocus+=(_,_)=>{if(string.IsNullOrWhiteSpace(text.Text))context.SetInputNumber?.Invoke(key,null);else if(double.TryParse(text.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out double v)&&double.IsFinite(v))context.SetInputNumber?.Invoke(key,v);};var p=new W.DockPanel();var select=Button("↗",()=>context.PickSubscription?.Invoke(dialog,key,false,DataKind.Number));W.DockPanel.SetDock(select,W.Dock.Right);p.Children.Add(select);p.Children.Add(text);Row(rows,label,p);}Add(x,"X");Add(y,"Y");rows.Children.Add(Button("确定",dialog.Close));dialog.Content=rows;dialog.ShowDialog();Build();},"InputPair"+x);b.HorizontalContentAlignment=System.Windows.HorizontalAlignment.Left;Row(parent,caption,b);}
 void Mode(W.Panel parent,string key,string caption){var panel=new W.StackPanel{Orientation=W.Orientation.Horizontal};for(int i=0;i<2;i++){int value=i;var radio=new W.RadioButton{Name=key+i,Content=i==0?"点":"X/Y",GroupName="NImage"+key,Style=(Style)FindResource("LightRadio"),IsChecked=I(key)==i,Margin=new Thickness(0,0,16,0)};radio.Checked+=(_,_)=>{if(building)return;Set(key,value);Build();};panel.Children.Add(radio);}Row(parent,caption,panel);}
 void Build(){int selected=tabs.SelectedIndex;building=true;try{tabs.Items.Clear();var basic=Page("NImageBasic","基本参数");Header(basic,"图像输入");Input(basic,"InImage","图像源",DataKind.GrayImage);Header(basic,"标定参数");Mode(basic,"CalibPointInput","标定点输入");if(I("CalibPointInput")==0)Pair(basic,"MovePhysicalPointX","MovePhysicalPointY","物理坐标");else{Input(basic,"MovePhysicalPointX","物理坐标 X");Input(basic,"MovePhysicalPointY","物理坐标 Y");}Input(basic,"RotateAngle","旋转角度");Number(basic,"CalibPointTotalNum","平移次数");Number(basic,"RotPointTotalNum","旋转次数");if(NImageUiRules.ShowAutomaticCoordinates(I("CalibPointInput"),Label("MovePhysicalPointX")+Label("MovePhysicalPointY"),Label("MovePhysicalPointX"),Label("MovePhysicalPointY"),Label("RotateAngle"))){Header(basic,"物理坐标系参数");foreach(var f in new[]{("BasePointX","基准坐标 X"),("BasePointY","基准坐标 Y"),("MoveAlignX","X向移动步长"),("MoveAlignY","Y向移动步长")})Number(basic,f.Item1,f.Item2);Choice(basic,"MoveFirstType","移动优先",new Dictionary<int,string>{{1,"X优先"},{2,"Y优先"}});Number(basic,"ChangeDirectionMoveTime","换向次数");if(NImageUiRules.ShowRotationCoordinates(I("RotPointTotalNum"))){Number(basic,"BaseAngle","基准角度");Number(basic,"MoveAngle","旋转步长");}}
  Header(basic,"矩阵修正");Toggle(basic,"HomoFixEnable","矩阵修正");if(B("HomoFixEnable")){Mode(basic,"InputMode","输入方式");if(I("InputMode")==0){Pair(basic,"PicPointX","PicPointY","图像点");Pair(basic,"PhysicalPointX","PhysicalPointY","物理点");}else{Input(basic,"PicPointX","图像坐标 X");Input(basic,"PicPointY","图像坐标 Y");Input(basic,"PhysicalPointX","物理坐标 X");Input(basic,"PhysicalPointY","物理坐标 Y");}}
  Header(basic,"标定文件");Toggle(basic,"RefreshFileEnable","更新标定文件");var path=new W.TextBox{Name="CalibPathName",Text=values["CalibPathName"].GetString()??"",Height=28};path.LostKeyboardFocus+=(_,_)=>{if(!building)Set("CalibPathName",path.Text);};Row(basic,"标定文件路径",path);var export=Button("生成标定文件",()=>{var d=new Microsoft.Win32.SaveFileDialog{Filter="标定文件|*.xml",DefaultExt=".xml"};if(d.ShowDialog(this)==true)try{save?.Invoke(d.FileName);Set("CalibPathName",d.FileName);Build();}catch(Exception ex){System.Windows.MessageBox.Show(this,ex.Message,"保存失败");}},"SaveNImageCalibration");export.IsEnabled=save is not null;basic.Children.Add(export);
  var run=Page("NImageRun","运行参数");Header(run,"运行参数");Toggle(run,"CareraMove","相机移动");Choice(run,"CalibBoardType","标定板类型",NImageUiRules.BoardTypes);Choice(run,"FilterStatus","滤波状态",new Dictionary<int,string>{{1,"执行滤波"},{2,"无滤波"}});run.Children.Add(Button("清除图像",()=>{Set("ClearRevision",checked(I("ClearRevision")+1));clear?.Invoke();},"ClearNImageFrames"));tabs.Items.Add(new W.TabItem{Name="NImageResult",Header="结果显示",Content=new W.ScrollViewer{Content=result}});tabs.SelectedIndex=selected>=0&&selected<tabs.Items.Count?selected:0;
 }finally{building=false;}}
 async Task Execute(){if(running||closed)return;running=true;once.IsEnabled=false;try{var r=await context.Run(values.ToDictionary(p=>p.Key,p=>p.Value.Clone()));result.Text=r.Status+"\n"+r.Message+"\n"+string.Join("\n",r.Outputs.Where(p=>p.Value.Kind is DataKind.Number or DataKind.Integer).Select(p=>p.Key+": "+p.Value.Value));}catch(Exception ex){continuous=false;System.Windows.MessageBox.Show(this,ex.Message,"执行失败");}finally{running=false;once.IsEnabled=!continuous;}}
}
